import{_ as s,C as a,o as i,c as d,a2 as t,E as r}from"./chunks/framework.BxGh02fV.js";const f=JSON.parse('{"title":"Choosing your setup","description":"","frontmatter":{"title":"Choosing your setup"},"headers":[],"relativePath":"en/guide/setup.md","filePath":"en/guide/setup.md"}'),n={name:"en/guide/setup.md"};function h(l,e,c,u,p,m){const o=a("Ask");return i(),d("div",null,[e[0]||(e[0]=t('<h1 id="choosing-your-setup" tabindex="-1">Choosing your setup <a class="header-anchor" href="#choosing-your-setup" aria-label="Permalink to &quot;Choosing your setup&quot;">​</a></h1><p>Before creating or adopting a project, two choices shape how Effortless works with you: <strong>how the agent moves forward</strong> (the work mode) and <strong>where the code lives</strong> (the module layout). Both can change later, but setting them right at the start saves detours.</p><p>A third point matters just as much: <strong>where you start your agent</strong>. The best experience comes from a command-line agent opened at the project root — see <a href="/Effortless/en/agent/#working-at-your-best-the-agent-opened-at-the-project-root">Working at your best</a>.</p><h2 id="the-work-mode" tabindex="-1">The work mode <a class="header-anchor" href="#the-work-mode" aria-label="Permalink to &quot;The work mode&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>The agent</th><th>The engine</th><th>For whom</th></tr></thead><tbody><tr><td><strong>Full</strong></td><td>moves on its own, with no intermediate validation</td><td>blocks nothing</td><td>you know Effortless and trust your agent</td></tr><tr><td><strong>Semi-auto</strong></td><td>proposes; you validate the key milestones</td><td>disables its execution tools: delivery, code regrouping, autonomous loop, team loop</td><td>you want to stay in control of what runs</td></tr><tr><td><strong>Tutored</strong></td><td>moves step by step, explains and confirms each step</td><td>blocks nothing: it is an instruction for the agent</td><td>you are discovering Effortless or the OPALE method</td></tr></tbody></table><p>A created or adopted project starts in <strong>Full</strong>. Change the mode at any time in the <a href="/Effortless/en/guide/settings.html">project settings</a>, or through the agent with <code>effortless_mode_set</code>.</p><div class="warning custom-block"><p class="custom-block-title">Semi-auto and adoption</p><p>In semi-auto, the <strong>Group code</strong> step of <a href="/Effortless/en/guide/adopt.html">adopting an existing project</a> is refused: it moves files. Adopt the project in Full or Tutored, then switch to semi-auto.</p></div><h2 id="the-code-layout" tabindex="-1">The code layout <a class="header-anchor" href="#the-code-layout" aria-label="Permalink to &quot;The code layout&quot;">​</a></h2><p>Effortless separates <strong>steering</strong> from <strong>code</strong>. Steering (<code>effortless.json</code>, <code>.effortless/</code>, <code>blueprints/</code>) always lives at the project root. Code is declared as <strong>modules</strong> (&quot;stacks&quot;): each has an id, a location, its languages and its development standards. The <a href="/Effortless/en/guide/modules.html">Modules</a> screen shows them all.</p><h3 id="one-repository-code-at-the-root" tabindex="-1">One repository, code at the root <a class="header-anchor" href="#one-repository-code-at-the-root" aria-label="Permalink to &quot;One repository, code at the root&quot;">​</a></h3><p>The simplest case. With no declaration, the project has one implicit module, <code>default</code>, covering the root. Nothing to do.</p><h3 id="several-modules-inside-the-project" tabindex="-1">Several modules inside the project <a class="header-anchor" href="#several-modules-inside-the-project" aria-label="Permalink to &quot;Several modules inside the project&quot;">​</a></h3><p>A single repository with several parts — an app, an API, documentation. Each module lives in <code>codebase/&lt;module&gt;/</code>. Declare it from the <a href="/Effortless/en/guide/create.html">creation assistant</a> (Stack step), from <strong>Preferences › Stack model</strong>, or through the agent with <code>effortless_stack_add</code>. <a href="/Effortless/en/guide/adopt.html">Adopting an existing project</a> moves the root code into <code>codebase/&lt;module&gt;/</code>.</p><h3 id="an-external-module-with-its-own-repository" tabindex="-1">An external module, with its own repository <a class="header-anchor" href="#an-external-module-with-its-own-repository" aria-label="Permalink to &quot;An external module, with its own repository&quot;">​</a></h3><p>A module&#39;s code lives outside the project, in another git repository you also develop. Declare it with its path and <code>git: true</code>:</p>',15)),r(o,{say:"Declare the api module, whose code is in ../billing-api, with its own git repository.",verb:"effortless_stack_add",family:"stacks",args:'{"id":"api","path":"../billing-api","git":true}'}),e[1]||(e[1]=t('<p>Effortless then follows that repository like the project&#39;s own: <a href="/Effortless/en/guide/drift.html">drift</a> is read there, and the anti-drift hook is installed there too when you install it.</p><h3 id="shared-sources-on-the-side" tabindex="-1">Shared sources, on the side <a class="header-anchor" href="#shared-sources-on-the-side" aria-label="Permalink to &quot;Shared sources, on the side&quot;">​</a></h3><p>A module&#39;s code lives in a repository you <strong>share</strong> — a library common to several of your projects, a third-party repository — that you do not want to instrument. Declare it with its path, <strong>without</strong> <code>git: true</code>:</p>',3)),r(o,{say:"Declare the core module, whose shared code is in ../common-core, without tracking it.",verb:"effortless_stack_add",family:"stacks",args:'{"id":"core","path":"../common-core"}'}),e[2]||(e[2]=t('<p>Effortless then works alongside those sources: it installs no hook there and commits nothing there. In return, drift is not watched there. <code>effortless_stack_list</code> marks this module <strong>NON SUIVIE</strong> (not tracked): that is intended, the label simply reminds you of the choice.</p><h2 id="the-anti-drift-hook-when-and-where" tabindex="-1">The anti-drift hook: when, and where <a class="header-anchor" href="#the-anti-drift-hook-when-and-where" aria-label="Permalink to &quot;The anti-drift hook: when, and where&quot;">​</a></h2><p>The anti-drift pre-commit hook refuses a code commit when no task is in progress. It is <strong>never installed by default</strong>: neither at creation nor at adoption.</p><ul><li>You install it from the <a href="/Effortless/en/guide/drift.html">Drift</a> screen (<strong>Install the pre-commit hook</strong>) or through the agent with <code>effortless_drift_hook_install</code>.</li><li>It goes on the project repository, and on every module declared with <code>git: true</code>.</li><li>It never goes on shared sources (an external module without <code>git: true</code>).</li><li>It never replaces a pre-commit hook that is not Effortless&#39;s: the installation is refused, and the refusal names the file.</li></ul><h2 id="which-choice-for-which-case" tabindex="-1">Which choice for which case <a class="header-anchor" href="#which-choice-for-which-case" aria-label="Permalink to &quot;Which choice for which case&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your situation</th><th>Mode</th><th>Layout</th></tr></thead><tbody><tr><td>You are discovering Effortless on a small project</td><td>Tutored</td><td>one repository</td></tr><tr><td>You want to validate what runs</td><td>Semi-auto</td><td>depending on the project</td></tr><tr><td>One repository with an app, an API, documentation</td><td>Full or Semi-auto</td><td>modules in <code>codebase/</code></td></tr><tr><td>The code is spread over several repositories you develop</td><td>Full or Semi-auto</td><td>external modules with <code>git: true</code></td></tr><tr><td>You rely on a common library you must neither modify nor instrument</td><td>your call</td><td>shared sources (without <code>git: true</code>)</td></tr><tr><td>An existing repository whose structure must stay as it is</td><td>your call</td><td>create the project without adoption, then declare the modules where they are, with <code>path</code></td></tr></tbody></table>',6))])}const w=s(n,[["render",h]]);export{f as __pageData,w as default};
